void tick_screen_kookschema() {
}

typedef void (*tick_screen_func_t)();
tick_screen_func_t tick_screen_funcs[] = {
    tick_screen_main,
    tick_screen_verbinden,
    tick_screen_schema,
    tick_screen_maischen,
    tick_screen_maischen_pauze,
    tick_screen_stap_bewerken,
    tick_screen_stop_bevestigen,
    tick_screen_spoelen,
    tick_screen_koken,
    tick_screen_sensor_fout,
    tick_screen_instellingen,
    tick_screen_web_app,
    tick_screen_numpad,
    tick_screen_kookschema,
};
void tick_screen(int screen_index) {
    if (screen_index >= 0 && screen_index < 14) {
        tick_screen_funcs[screen_index]();
    }
}
void tick_screen_by_id(enum ScreensEnum screenId) {
    tick_screen(screenId - 1);
}

