//
// Color themes
//

uint32_t active_theme_index = 0;

//
//
//

void create_screens() {

// Set default LVGL theme
    lv_display_t *dispp = lv_display_get_default();
    lv_theme_t *theme = lv_theme_default_init(dispp, lv_palette_main(LV_PALETTE_BLUE), lv_palette_main(LV_PALETTE_RED), false, LV_FONT_DEFAULT);
    lv_display_set_theme(dispp, theme);
    
    // Initialize screens
    // Create screens
    create_screen_main();
    create_screen_verbinden();
    create_screen_schema();
    create_screen_maischen();
    create_screen_maischen_pauze();
    create_screen_stap_bewerken();
    create_screen_stop_bevestigen();
    create_screen_spoelen();
    create_screen_koken();
    create_screen_sensor_fout();
    create_screen_instellingen();
    create_screen_web_app();
    create_screen_numpad();
    create_screen_kookschema();
}